function volumeQuestions() {
	if (ROWS$11.length !== 100) throw new Error(`volume sheet ${ROWS$11.length}`);
	return ROWS$11.map((item, index) => ({
		...item,
		level: index < 34 ? "basic" : index < 67 ? "core" : "hard"
	}));
}
var pan = (left, right) => ({
	kind: "balance",
	left,
	right
});
var rect = (length, width, note) => ({
	kind: "rect",
	length,
	width,
	note
});
var tri = (base, height, note) => ({
	kind: "tri",
	base,
	height,
	note
});
var trap = (top, bottom, height, note) => ({
	kind: "trap",
	top,
	bottom,
	height,
	note
});
function row$10(stem, answer, wrong, why, figure) {
	return {
		stem,
		answer,
		wrong,
		why,
		figure
	};
}
