function equationQuestions() {
	if (ROWS$10.length !== 100) throw new Error(`equation sheet ${ROWS$10.length}`);
	return ROWS$10.map((item, index) => ({
		...item,
		level: index < 34 ? "basic" : index < 67 ? "core" : "hard"
	}));
}
var grid = (shaded) => ({
	kind: "grid",
	shaded
});
var bar = (parts, shaded) => ({
	kind: "pbar",
	parts,
	shaded
});
var line$2 = (at) => ({
	kind: "pline",
	at
});
var chart = (known, value) => ({
	kind: "pchart",
	known,
	value
});
function row$9(stem, answer, wrong, why, figure) {
	return {
		stem,
		answer,
		wrong,
		why,
		figure
	};
}
