function misuseQuestions() {
	if (ROWS$1.length !== 100) throw new Error(`misuse sheet ${ROWS$1.length}`);
	return ROWS$1.map((item, index) => ({
		...item,
		wrong: item.wrong,
		level: index < 34 ? "basic" : index < 67 ? "core" : "hard"
	}));
}
