function fracHard() {
	const out = [];
	const bank = [
		["0.7", .7],
		["3/4", .75],
		["0.8", .8],
		["2/5", .4],
		["0.66", .66],
		["2/3", 2 / 3],
		["0.666", .666],
		["1/2", .5],
		["0.45", .45],
		["3.8", 3.8],
		["3.11", 3.11],
		["1.65", 1.65],
		["1.7", 1.7],
		["8/5", 1.6],
		["7/4", 1.75]
	];
	let made = 0;
	for (let i = 0; i < bank.length && made < 24; i += 1) for (let j = i + 1; j < bank.length && made < 24; j += 1) for (let k = j + 1; k < bank.length && made < 24; k += 1) {
		const rows = [
			bank[i],
			bank[j],
			bank[k]
		];
		if (new Set(rows.map((row) => money(row[1] * 1e3))).size < 3) continue;
		const ordered = [...rows].sort((a, b) => a[1] - b[1]);
		const answer = ordered.map((row) => row[0]).join(" < ");
		const reversed = [...ordered].reverse().map((row) => row[0]).join(" < ");
		const swapped = [
			ordered[0][0],
			ordered[2][0],
			ordered[1][0]
		].join(" < ");
		const original = rows.map((row) => row[0]).join(" < ");
		if ([
			reversed,
			swapped,
			original
		].filter((item) => item !== answer).length < 3 && (/* @__PURE__ */ new Set([
			reversed,
			swapped,
			original,
			"不能排"
		])).size < 4) continue;
		out.push(tq("hard", `把 ${rows.map((row) => row[0]).join("、")} 由小至大排列。`, answer, [
			reversed,
			swapped,
			original === answer ? "三數一樣大" : original
		], `化成小數：${ordered.map((row) => `${row[0]}≈${fmt(money(row[1]))}`).join("，")}。`));
		made += 1;
	}
	const days = [
		["卓文", 2.7],
		["美欣", 1.3],
		["子博", 1.95],
		["阿凱", 2.25],
		["小榆", 1.6]
	];
	for (let i = 0; i < days.length; i += 1) for (let j = i + 1; j < days.length; j += 1) {
		const fast = days[i][1] < days[j][1] ? days[i] : days[j];
		const slow = fast[0] === days[i][0] ? days[j] : days[i];
		const diff = money(Math.abs(days[i][1] - days[j][1]));
		const hours = Math.floor(diff + 1e-9);
		const mins = Math.round((diff - hours) * 60);
		out.push(tq("hard", `${days[i][0]}今天用了 ${fmt(days[i][1])} 小時，${days[j][0]}今天用了 ${fmt(days[j][1])} 小時。誰較快？相差多少？`, `${fast[0]}較快，相差 ${hours} 小時 ${mins} 分鐘`, [
			`${slow[0]}較快，相差 ${hours} 小時 ${mins} 分鐘`,
			"兩人一樣快",
			`${fast[0]}較快，相差 ${fmt(diff)} 分鐘`
		], `${fmt(slow[1])} − ${fmt(fast[1])} = ${fmt(diff)} 小時 = ${hours} 小時 ${mins} 分鐘。`));
	}
	return out;
}
