function pieCore() {
	const out = [];
	for (const pie of [
		{
			title: "糖果",
			parts: [
				["可樂糖", 24],
				["蘋果糖", 12],
				["朱古力", 9],
				["薄荷糖", 9],
				["芒果糖", 18]
			],
			total: 72
		},
		{
			title: "遊戲",
			parts: [
				["旋轉木馬", 20],
				["摩天輪", 10],
				["滑梯", 15],
				["小火車", 5]
			],
			total: 50
		},
		{
			title: "小食",
			parts: [
				["爆谷", 16],
				["糖畫", 8],
				["果汁", 8],
				["熱狗", 8]
			],
			total: 40
		}
	]) {
		for (const [name, count] of pie.parts) {
			const pct = count / pie.total * 100;
			if (Math.abs(pct - Math.round(pct)) > 1e-6) continue;
			out.push(nq("core", `${pie.title}圓形圖：${pie.parts.map(([label, n]) => `${label} ${n}`).join("、")}，共 ${pie.total}。${name}佔百分之幾？`, pct, [
				count,
				pie.total,
				Math.round(pct / 10) || 1
			], `${count} ÷ ${pie.total} = ${fmt(pct)}%。`));
		}
		const [a, b] = [pie.parts[0], pie.parts[1]];
		const ratio = frac(a[1], b[1]);
		out.push(tq("core", `${a[0]}的數量是${b[0]}的多少？用最簡分數。`, ratio, [
			frac(b[1], a[1]),
			`${a[1]}/${pie.total}`,
			`${a[1]}/${b[1] + a[1]}`
		], `${a[1]} ÷ ${b[1]} = ${ratio}。`));
	}
	return out;
}
