function baseCore() {
	const out = [];
	for (const [claim, answer, , why] of [
		[
			"7 斤 9 両 = 79 両",
			"不正確，是 121 両",
			false,
			"7 × 16 + 9 = 121，不是 79。"
		],
		[
			"8 呎 11 吋 = 107 吋",
			"正確",
			true,
			"8 × 12 + 11 = 107。"
		],
		[
			"11 磅 12 安士 = 188 安士",
			"正確",
			true,
			"11 × 16 + 12 = 188。"
		],
		[
			"135 吋 = 8 呎 7 吋",
			"不正確，是 11 呎 3 吋",
			false,
			"135 ÷ 12 = 11 餘 3。"
		],
		[
			"200 両 = 12 斤 8 両",
			"正確",
			true,
			"200 ÷ 16 = 12 餘 8。"
		],
		[
			"147 安士 = 12 磅 3 安士",
			"不正確，是 9 磅 3 安士",
			false,
			"147 ÷ 16 = 9 餘 3。"
		]
	]) out.push(tq("core", `「${claim}」對嗎？`, answer, [
		"正確",
		"不正確，要當成十進制",
		"單位不能互換"
	].filter((item) => item !== answer), why));
	for (const total of [
		121,
		79,
		200,
		147,
		135,
		107,
		188,
		64,
		80,
		95,
		160,
		50
	]) {
		const catty = Math.floor(total / 16);
		const tael = total % 16;
		out.push(tq("core", `${total} 両等於多少斤多少両？`, `${catty} 斤 ${tael} 両`, [
			`${Math.floor(total / 10)} 斤 ${total % 10} 両`,
			`${total} 斤 0 両`,
			`${catty + 1} 斤 ${tael} 両`
		], `${total} ÷ 16 = ${catty} 餘 ${tael}。`));
		const foot = Math.floor(total / 12);
		const inch = total % 12;
		out.push(tq("core", `${total} 吋等於多少呎多少吋？`, `${foot} 呎 ${inch} 吋`, [
			`${Math.floor(total / 10)} 呎 ${total % 10} 吋`,
			`${foot} 呎 ${inch + 1} 吋`,
			`${inch} 呎 ${foot} 吋`
		], `${total} ÷ 12 = ${foot} 餘 ${inch}。`));
		const pound = Math.floor(total / 16);
		const ounce = total % 16;
		out.push(tq("core", `${total} 安士等於多少磅多少安士？`, `${pound} 磅 ${ounce} 安士`, [
			`${Math.floor(total / 10)} 磅 ${total % 10} 安士`,
			`${ounce} 磅 ${pound} 安士`,
			`${pound} 磅 16 安士`
		], `${total} ÷ 16 = ${pound} 餘 ${ounce}。`));
	}
	return out;
}
